<div id="affirmation-toast" class="fixed inset-0 bg-brand-emerald/40 backdrop-blur-sm flex items-center justify-center z-50 p-4 {{ session('success') || session('status') || session('error') ? '' : 'hidden' }}" role="dialog" aria-modal="true" aria-labelledby="toast-title"><div id="affirmation-content" class="bg-white text-gray-900 border-2 border-brand-emerald p-7 md:p-10 rounded-3xl shadow-2xl max-w-xl w-full text-center space-y-5 transform scale-95 transition-transform duration-300"><div class="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center text-brand-emerald mx-auto"><i class="fas {{ session('error') ? 'fa-exclamation-triangle text-rose-600' : 'fa-check-circle' }} text-4xl"></i></div><div><h3 class="text-xl md:text-2xl font-black text-brand-emerald" id="toast-title">{{ session('error') ? 'Perhatian / Kendala' : 'Transaksi berhasil diperbarui' }}</h3><p class="text-sm text-brand-slate font-semibold mt-2" id="toast-msg">{{ session('success') ?? session('status') ?? session('error') }}</p></div><button type="button" onclick="closeAffirmationToast()" class="px-7 py-3 bg-brand-emerald hover:opacity-90 text-white font-black rounded-xl">Selesai & Tutup</button></div></div>
<script>function closeAffirmationToast(){const t=document.getElementById('affirmation-toast'),c=document.getElementById('affirmation-content');c.classList.add('scale-95');setTimeout(()=>t.classList.add('hidden'),180)}function triggerToast(title,message){document.getElementById('toast-title').innerText=title;document.getElementById('toast-msg').innerText=message;const t=document.getElementById('affirmation-toast'),c=document.getElementById('affirmation-content');t.classList.remove('hidden');setTimeout(()=>c.classList.replace('scale-95','scale-100'),30)}@if(session('success')||session('status')||session('error'))document.addEventListener('DOMContentLoaded',()=>setTimeout(()=>document.getElementById('affirmation-content').classList.replace('scale-95','scale-100'),30));@endif</script>
